INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW004S273N8N5XREGJ2Q', 25.0297, 121.56819, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 A96。日期為計畫上網日期。原因：關鍵因子：樹冠受截幹修剪危害，等勢枝，修枝後切口無法癒合產生腐朽空洞。；處理建議：樹木截幹後癒合不良有影響結構之虞，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680031125', 'pkl:removal_D3BB0AD389D1F53B:0:A96', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
INSERT OR IGNORE INTO reports (id, lat, lng, species, causes, dispositions, evidence, source, note, link, observed_at, protected_tree_id, inventory_tree_id, external_ref, status, reporter_hash, created_at) VALUES ('01M34XGW004SGMEWD5HYV2NMN8', 25.02956, 121.56849, '黑板樹', '[3,20]', '[]', 3, 3, '計畫移除。臺北捷運環狀線東環段CF760區段標樹木移除計畫（狀態不明）。計畫書編號 B133。日期為計畫上網日期。原因：關鍵因子：無枝葉生長、全株均小葉，移除枯枝等不健康部位樹型完全崩壞，修枝後復原法癒合產生腐朽。；處理建議：無枝葉生長，主枝明顯腐朽影響安全，建議移除。', 'https://pkl.gov.taipei/News_Content.aspx?n=2939F8C5A5AFE474&sms=F8C3B4B0B10BF291&s=D3BB0AD389D1F53B', '2026-09-23', NULL, 'SY1680022053', 'pkl:removal_D3BB0AD389D1F53B:0:B133', 0, NULL, strftime('%Y-%m-%dT%H:%M:%fZ', 'now'));
